import { ChevronLeftIcon, ChevronRightIcon } from '@advui/icons'
import { forwardRef } from 'react'
import { type GetProps, type TamaguiElement, View, XStack, styled } from 'tamagui/unstyled'
import { Button } from '../button/Button'
import { IconButton } from '../icon-button/IconButton'
import { Text } from '../typography/Text'
import { ToggleGroup } from '../toggle-group/ToggleGroup'
import { useControllableState } from '../../hooks/useControllableState'
import { AgendaView } from './AgendaView'
import { addDays, addMonths, isSameDay, startOfDay, weekDays } from './dates'
import { type CalendarEvent, eventEnd } from './events'
import { MonthView } from './MonthView'
import {
  type EventCalendarLabels,
  type EventCalendarView,
  type ViewContext,
  defaultLabels,
  useFormats,
} from './parts'
import { TimeGrid } from './TimeGrid'

const EventCalendarFrame = styled(View, {
  displayName: 'EventCalendar',
  gap: '3',
})

const allViews: EventCalendarView[] = ['month', 'week', 'day', 'agenda']

export interface EventCalendarProps extends Omit<
  GetProps<typeof EventCalendarFrame>,
  'children' | 'defaultValue'
> {
  events: readonly CalendarEvent[]
  /** The view shown (controlled). */
  view?: EventCalendarView
  defaultView?: EventCalendarView
  onViewChange?: (view: EventCalendarView) => void
  /** The views to switch between, in order. Default: all four. */
  views?: EventCalendarView[]
  /** A day in the shown month, week or day (controlled). */
  date?: Date
  /** Default: today. */
  defaultDate?: Date
  onDateChange?: (date: Date) => void
  /** Makes events buttons. */
  onEventPress?: (event: CalendarEvent) => void
  /**
   * Called when a day is pressed: a month day's number, or a week day's
   * heading. With the day view among `views`, that day opens there too.
   */
  onDatePress?: (date: Date) => void
  /** 0 = Sunday, 1 = Monday… Default 0. */
  weekStartsOn?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  /** BCP 47 locale for dates and times. Defaults to the device locale. */
  locale?: string
  /** Override "today" (tests, screenshots). */
  today?: Date
  /** Lines of events a month day shows before “+2 more”. Default 3. */
  maxEventsPerDay?: number
  /** Height of the scrolling hours in the week and day views. Default `128`. */
  timeGridHeight?: GetProps<typeof View>['height']
  /** The hour at the top when the week or day view opens. Default 8. */
  scrollToHour?: number
  labels?: Partial<EventCalendarLabels>
}

/**
 * Events on a month grid, a week or a day of hours, or an agenda list, with
 * Today, previous and next, and a view switcher.
 */
export const EventCalendar = forwardRef<TamaguiElement, EventCalendarProps>(function EventCalendar(
  {
    events,
    view: viewProp,
    defaultView = 'month',
    onViewChange,
    views = allViews,
    date: dateProp,
    defaultDate,
    onDateChange,
    onEventPress,
    onDatePress,
    weekStartsOn = 0,
    locale,
    today: todayProp,
    maxEventsPerDay = 3,
    timeGridHeight = '128',
    scrollToHour = 8,
    labels: labelsProp,
    ...props
  },
  ref,
) {
  const today = startOfDay(todayProp ?? new Date())
  const labels = { ...defaultLabels, ...labelsProp }
  const formats = useFormats(locale)
  const [view, setView] = useControllableState({
    value: viewProp,
    defaultValue: defaultView,
    onChange: onViewChange,
  })
  const [date, setDate] = useControllableState({
    value: dateProp,
    defaultValue: startOfDay(defaultDate ?? today),
    onChange: onDateChange,
  })

  const hasDayView = views.includes('day')
  const openDay =
    hasDayView || onDatePress
      ? (day: Date) => {
          onDatePress?.(day)
          if (!hasDayView) return
          setDate(day)
          setView('day')
        }
      : null

  const eventLabel = (event: CalendarEvent) => {
    const end = eventEnd(event)
    const startDay = formats.day.format(event.start)
    if (event.allDay) {
      const days = isSameDay(event.start, end)
        ? startDay
        : `${startDay} ${labels.to} ${formats.day.format(end)}`
      return `${event.title}, ${labels.allDay}, ${days}`
    }
    const from = formats.time.format(event.start)
    const until = formats.time.format(end)
    return isSameDay(event.start, end)
      ? `${event.title}, ${startDay}, ${from} ${labels.to} ${until}`
      : `${event.title}, ${startDay} ${from} ${labels.to} ${formats.day.format(end)} ${until}`
  }

  const context: ViewContext = {
    events,
    today,
    weekStartsOn,
    formats,
    labels,
    openDay,
    onEventPress: onEventPress ?? null,
    eventLabel,
  }

  const week = weekDays(date, weekStartsOn)
  const title =
    view === 'week'
      ? `${formats.monthDay.format(week[0]!)} – ${formats.monthDayYear.format(week[6]!)}`
      : view === 'day'
        ? formats.day.format(date)
        : formats.month.format(date)
  const step = (direction: 1 | -1) =>
    setDate(
      view === 'week'
        ? addDays(date, 7 * direction)
        : view === 'day'
          ? addDays(date, direction)
          : addMonths(date, direction),
    )
  const [previousLabel, nextLabel] =
    view === 'week'
      ? [labels.previousWeek, labels.nextWeek]
      : view === 'day'
        ? [labels.previousDay, labels.nextDay]
        : [labels.previousMonth, labels.nextMonth]

  return (
    <EventCalendarFrame ref={ref} {...props}>
      <XStack alignItems="center" justifyContent="space-between" flexWrap="wrap" gap="2">
        <XStack alignItems="center" gap="1" flexShrink={1}>
          <Button size="sm" variant="outline" onPress={() => setDate(today)}>
            {labels.today}
          </Button>
          <IconButton
            size="sm"
            variant="ghost"
            icon={<ChevronLeftIcon />}
            aria-label={previousLabel}
            onPress={() => step(-1)}
          />
          <IconButton
            size="sm"
            variant="ghost"
            icon={<ChevronRightIcon />}
            aria-label={nextLabel}
            onPress={() => step(1)}
          />
          <Text size="lg" weight="semibold" marginLeft="1" flexShrink={1} aria-live="polite">
            {title}
          </Text>
        </XStack>
        {views.length > 1 ? (
          <ToggleGroup
            type="single"
            size="sm"
            variant="outline"
            value={view}
            // Pressing the shown view again keeps it.
            onValueChange={(next) => next && setView(next as EventCalendarView)}
            aria-label={labels.view}
          >
            {views.map((name) => (
              <ToggleGroup.Item key={name} value={name}>
                {labels[name]}
              </ToggleGroup.Item>
            ))}
          </ToggleGroup>
        ) : null}
      </XStack>
      {view === 'month' ? (
        <MonthView month={date} maxEventsPerDay={maxEventsPerDay} {...context} />
      ) : view === 'agenda' ? (
        <AgendaView month={date} {...context} />
      ) : (
        <TimeGrid
          // A new view opens at `scrollToHour`; moving by week or day keeps the place.
          key={view}
          days={view === 'week' ? week : [date]}
          height={timeGridHeight}
          scrollToHour={scrollToHour}
          {...context}
        />
      )}
    </EventCalendarFrame>
  )
})

import { View, XStack, isWeb } from 'tamagui/unstyled'
import { Hide, Show } from '../show-hide/ShowHide'
import { Text } from '../typography/Text'
import { VisuallyHidden } from '../visually-hidden/VisuallyHidden'
import { dayKey, isSameDay, isSameMonth, monthWeeks } from './dates'
import { eventsOnDay } from './events'
import { EventButton, type ViewContext, buttonProps, tones, webRole } from './parts'

export interface MonthViewProps extends ViewContext {
  month: Date
  maxEventsPerDay: number
}

/**
 * Four to six weeks of days, each with its first events. Phones show a dot
 * per event instead: the day's number opens it, or the agenda lists them.
 */
export function MonthView({ month, maxEventsPerDay, ...context }: MonthViewProps) {
  const { formats, weekStartsOn } = context
  const weeks = monthWeeks(month, weekStartsOn)
  return (
    <View
      role={webRole('table')}
      aria-label={formats.month.format(month)}
      borderWidth={1}
      borderColor="border"
      borderRadius="lg"
      overflow="hidden"
    >
      <XStack
        role={webRole('row')}
        backgroundColor="muted"
        borderBottomWidth={1}
        borderColor="border"
      >
        {weeks[0]!.map((day) => (
          <View
            key={day.getDay()}
            role={webRole('columnheader')}
            aria-label={formats.weekdayLong.format(day)}
            flex={1}
            flexBasis={0}
            alignItems="center"
            paddingVertical="1-5"
          >
            <Text size="xs" weight="medium" tone="muted" aria-hidden>
              {formats.weekdayShort.format(day)}
            </Text>
          </View>
        ))}
      </XStack>
      {weeks.map((week, row) => (
        <XStack
          key={dayKey(week[0]!)}
          role={webRole('row')}
          {...(row < weeks.length - 1 && { borderBottomWidth: 1, borderColor: 'border' })}
        >
          {week.map((day, column) => (
            <MonthDay
              key={dayKey(day)}
              day={day}
              inMonth={isSameMonth(day, month)}
              last={column === 6}
              maxEvents={maxEventsPerDay}
              {...context}
            />
          ))}
        </XStack>
      ))}
    </View>
  )
}

function MonthDay({
  day,
  inMonth,
  last,
  maxEvents,
  events,
  today,
  formats,
  labels,
  openDay,
  onEventPress,
  eventLabel,
}: ViewContext & { day: Date; inMonth: boolean; last: boolean; maxEvents: number }) {
  const dayEvents = eventsOnDay(events, day)
  const isToday = isSameDay(day, today)
  // One line fewer when a "more" line is needed, so a day never grows past
  // its first `maxEvents` lines.
  const shown = dayEvents.length > maxEvents ? dayEvents.slice(0, maxEvents - 1) : dayEvents
  const hidden = dayEvents.length - shown.length
  const name = `${formats.day.format(day)}${isToday && !isWeb ? `, ${labels.todayMarker}` : ''}, ${labels.events(dayEvents.length)}`
  const number = (
    <Text
      size="xs"
      weight={isToday ? 'semibold' : 'medium'}
      color={isToday ? 'primaryForeground' : inMonth ? 'foreground' : 'mutedForeground'}
      aria-hidden
    >
      {day.getDate()}
    </Text>
  )
  return (
    <View
      role={webRole('cell')}
      flex={1}
      flexBasis={0}
      minWidth={0}
      minHeight="16 sm:24"
      padding="1"
      gap="0-5"
      {...(!last && { borderRightWidth: 1, borderColor: 'border' })}
    >
      {openDay ? (
        <View
          {...buttonProps(name)}
          aria-current={isToday ? 'date' : undefined}
          onPress={() => openDay(day)}
          width="7"
          height="7"
          padding={0}
          alignSelf="flex-start"
          alignItems="center"
          justifyContent="center"
          borderRadius="full"
          // After buttonProps, which clears a button's own background on web.
          backgroundColor={isToday ? 'primary' : 'transparent hover:accent press:accentHover'}
          outlineColor="focus-visible:ring"
          outlineStyle="focus-visible:solid"
          outlineWidth="focus-visible:2px"
          {...(!isWeb && { hitSlop: 8 })}
        >
          {number}
        </View>
      ) : (
        <View
          width="7"
          height="7"
          alignItems="center"
          justifyContent="center"
          borderRadius="full"
          {...(isToday && { backgroundColor: 'primary' })}
        >
          {number}
          <VisuallyHidden>{name}</VisuallyHidden>
        </View>
      )}
      <Hide below="sm">
        {shown.map((event) => {
          const tone = tones[event.tone ?? 'primary']
          return (
            <EventButton
              key={event.id}
              event={event}
              label={eventLabel(event)}
              onPress={onEventPress}
            >
              <Text size="xs" color={tone.color} truncate flex={1}>
                {event.title}
              </Text>
            </EventButton>
          )
        })}
        {hidden > 0 ? (
          openDay ? (
            <View
              {...buttonProps(`${labels.more(hidden)}, ${formats.day.format(day)}`)}
              onPress={() => openDay(day)}
              alignSelf="flex-start"
              paddingHorizontal="1"
              paddingVertical={0}
              borderRadius="sm"
              backgroundColor="transparent hover:accent press:accentHover"
              outlineColor="focus-visible:ring"
              outlineStyle="focus-visible:solid"
              outlineWidth="focus-visible:2px"
            >
              <Text size="xs" weight="medium" tone="muted" aria-hidden>
                +{labels.more(hidden)}
              </Text>
            </View>
          ) : (
            <Text size="xs" tone="muted" paddingHorizontal="1">
              +{labels.more(hidden)}
            </Text>
          )
        ) : null}
      </Hide>
      <Show below="sm">
        {dayEvents.length ? (
          // The day's name counts them; the dots only show they are there.
          <XStack gap="0-5" flexWrap="wrap" paddingHorizontal="1" aria-hidden>
            {dayEvents.slice(0, 4).map((event) => (
              <View
                key={event.id}
                width="1-5"
                height="1-5"
                borderRadius="full"
                backgroundColor={tones[event.tone ?? 'primary'].dot}
              />
            ))}
          </XStack>
        ) : null}
      </Show>
    </View>
  )
}

import { useEffect, useRef } from 'react'
import {
  type GetProps,
  type TamaguiElement,
  type Token,
  View,
  XStack,
  getTokenValue,
  isWeb,
} from 'tamagui/unstyled'
import { ScrollArea } from '../scroll-area/ScrollArea'
import { Sticky } from '../sticky/Sticky'
import { Text } from '../typography/Text'
import { VisuallyHidden } from '../visually-hidden/VisuallyHidden'
import { dayKey, isSameDay, minutesPerDay } from './dates'
import { eventEnd, eventsOnDay, placeEvents } from './events'
import { EventButton, type ViewContext, buttonProps, tones, webRole } from './parts'

const hours = Array.from({ length: 24 }, (_, hour) => hour)
// One hour row, and the time gutter beside the days.
const hourHeight = '12'
const gutterWidth = '14'
// A short event still gets room for one line: half an hour of height.
const minMinutes = 30
// Shorter than this, an event has one line: its title and start time.
const compactMinutes = 45

const percent = (minutes: number): `${number}%` => `${(minutes / minutesPerDay) * 100}%`

type NativeScrollView = { scrollTo: (options: { y: number; animated: boolean }) => void }

export interface TimeGridProps extends ViewContext {
  days: Date[]
  height: GetProps<typeof View>['height']
  /** The hour shown at the top when it opens. */
  scrollToHour: number
}

/**
 * The week and day views: all-day events above, timed ones on the hours of
 * their day. The days and the all-day row stay pinned while the hours scroll.
 */
export function TimeGrid({ days, height, scrollToHour, ...context }: TimeGridProps) {
  const { events, formats, labels, onEventPress, eventLabel } = context
  const scrollRef = useRef<TamaguiElement>(null)
  const scrolled = useRef(false)
  // The pinned header sits over the top of the hours, so the hour's offset
  // puts it just below the header. A little less shows its label, which
  // sits half above the line.
  const offset = Math.max(
    0,
    scrollToHour * (getTokenValue(hourHeight as Token, 'size') as number) -
      (getTokenValue('2' as Token, 'space') as number),
  )

  useEffect(() => {
    const node = scrollRef.current as HTMLElement | null
    if (isWeb && node) node.scrollTop = offset
  }, [offset])
  // Native: a ScrollView scrolls only once it is laid out.
  const onLayout = () => {
    if (scrolled.current) return
    scrolled.current = true
    ;(scrollRef.current as unknown as NativeScrollView | null)?.scrollTo({
      y: offset,
      animated: false,
    })
  }

  const allDay = days.map((day) => eventsOnDay(events, day).filter((event) => event.allDay))
  const single = days.length === 1

  return (
    <ScrollArea
      ref={scrollRef}
      height={height}
      borderWidth={1}
      borderColor="border"
      borderRadius="lg"
      {...(!isWeb && { onLayout })}
    >
      <View>
        <Sticky backgroundColor="background">
          <XStack borderBottomWidth={1} borderColor="border">
            <View width={gutterWidth} />
            {days.map((day) => (
              <DayHeader key={dayKey(day)} day={day} pressable={!single} {...context} />
            ))}
          </XStack>
          {allDay.some((list) => list.length) ? (
            <XStack borderBottomWidth={1} borderColor="border">
              <View width={gutterWidth} justifyContent="center" paddingHorizontal="1">
                <Text size="xs" tone="muted" textAlign="center" aria-hidden>
                  {labels.allDay}
                </Text>
              </View>
              {days.map((day, index) => (
                <View
                  key={dayKey(day)}
                  flex={1}
                  flexBasis={0}
                  minWidth={0}
                  gap="0-5"
                  padding="0-5"
                  borderLeftWidth={1}
                  borderColor="border"
                >
                  {allDay[index]!.map((event) => (
                    <EventButton
                      key={event.id}
                      event={event}
                      label={eventLabel(event)}
                      onPress={onEventPress}
                    >
                      <Text
                        size="xs"
                        color={tones[event.tone ?? 'primary'].color}
                        truncate
                        flex={1}
                      >
                        {event.title}
                      </Text>
                    </EventButton>
                  ))}
                </View>
              ))}
            </XStack>
          ) : null}
        </Sticky>
        <XStack>
          <View width={gutterWidth} aria-hidden>
            {hours.map((hour) => (
              <View key={hour} height={hourHeight} alignItems="flex-end" paddingRight="2">
                {/* Each label is centered on its hour's line; midnight has none. */}
                {hour > 0 ? (
                  <Text size="xs" tone="muted" marginTop="-2">
                    {formats.hour.format(new Date(2000, 0, 1, hour))}
                  </Text>
                ) : null}
              </View>
            ))}
          </View>
          {days.map((day) => (
            <DayColumn key={dayKey(day)} day={day} {...context} />
          ))}
        </XStack>
      </View>
    </ScrollArea>
  )
}

function DayColumn({
  day,
  events,
  formats,
  onEventPress,
  eventLabel,
}: ViewContext & { day: Date }) {
  const placed = placeEvents(events, day, minMinutes)
  return (
    <View
      flex={1}
      flexBasis={0}
      minWidth={0}
      position="relative"
      borderLeftWidth={1}
      borderColor="border"
      role={webRole('group')}
      {...(isWeb && { 'aria-label': formats.day.format(day) })}
    >
      {hours.map((hour) => (
        <View
          key={hour}
          height={hourHeight}
          {...(hour > 0 && { borderTopWidth: 1, borderColor: 'border' })}
        />
      ))}
      {placed.map(({ event, top, bottom, column, columns }) => {
        const tone = tones[event.tone ?? 'primary']
        return (
          <View
            key={event.id}
            position="absolute"
            top={percent(top)}
            height={percent(bottom - top)}
            left={`${(column / columns) * 100}%`}
            width={`${100 / columns}%`}
            padding="0-5"
          >
            <EventButton
              variant="block"
              event={event}
              label={eventLabel(event)}
              onPress={onEventPress}
            >
              {bottom - top < compactMinutes ? (
                // Too short for two lines: the title and start time on one.
                <Text size="xs" color={tone.color} numberOfLines={1} flexShrink={0}>
                  <Text size="xs" weight="semibold" color={tone.color}>
                    {event.title}
                  </Text>
                  {`, ${formats.time.format(event.start)}`}
                </Text>
              ) : (
                <>
                  <Text
                    size="xs"
                    weight="semibold"
                    color={tone.color}
                    // Side by side, a column is too narrow to wrap words into.
                    numberOfLines={columns > 1 ? 1 : 2}
                    flexShrink={0}
                  >
                    {event.title}
                  </Text>
                  <Text size="xs" color={tone.color} numberOfLines={1} flexShrink={0}>
                    {formats.time.format(event.start)} – {formats.time.format(eventEnd(event))}
                  </Text>
                </>
              )}
            </EventButton>
          </View>
        )
      })}
    </View>
  )
}

function DayHeader({
  day,
  pressable,
  today,
  formats,
  labels,
  openDay,
}: ViewContext & { day: Date; pressable: boolean }) {
  const isToday = isSameDay(day, today)
  const name = `${formats.day.format(day)}${isToday && !isWeb ? `, ${labels.todayMarker}` : ''}`
  const content = (
    <>
      <Text size="xs" tone={isToday ? 'primary' : 'muted'} aria-hidden>
        {formats.weekdayShort.format(day)}
      </Text>
      <Text size="lg" weight="semibold" color={isToday ? 'primaryText' : 'foreground'} aria-hidden>
        {day.getDate()}
      </Text>
    </>
  )
  const frame = {
    flex: 1,
    flexBasis: 0,
    minWidth: 0,
    alignItems: 'center',
    paddingVertical: '1-5',
    borderLeftWidth: 1,
    borderColor: 'border',
  } as const
  if (pressable && openDay) {
    return (
      <View
        {...buttonProps(name)}
        aria-current={isToday ? 'date' : undefined}
        onPress={() => openDay(day)}
        {...frame}
        paddingHorizontal={0}
        // After buttonProps, which clears the border and background on web.
        borderLeftWidth={1}
        backgroundColor="transparent hover:accent press:accentHover"
        outlineColor="focus-visible:ring"
        outlineStyle="focus-visible:solid"
        outlineWidth="focus-visible:2px"
        outlineOffset="focus-visible:-2px"
      >
        {content}
      </View>
    )
  }
  return (
    <View {...frame}>
      {content}
      <VisuallyHidden>{name}</VisuallyHidden>
    </View>
  )
}

import { View, XStack } from 'tamagui/unstyled'
import { Text } from '../typography/Text'
import { VStack } from '../layout/Stack'
import { dayKey, isSameDay, monthDays } from './dates'
import { eventEnd, eventsOnDay } from './events'
import { EventButton, type ViewContext, tones } from './parts'

/** The month's days that have events, as a list: it suits phones and screen readers. */
export function AgendaView({ month, ...context }: ViewContext & { month: Date }) {
  const { events, today, formats, labels, onEventPress, eventLabel } = context
  const days = monthDays(month)
    .map((day) => ({ day, events: eventsOnDay(events, day) }))
    .filter((entry) => entry.events.length)

  if (!days.length) {
    return (
      <View alignItems="center" padding="6" borderWidth={1} borderColor="border" borderRadius="lg">
        <Text size="sm" tone="muted">
          {labels.noEvents}
        </Text>
      </View>
    )
  }

  return (
    <VStack borderWidth={1} borderColor="border" borderRadius="lg" overflow="hidden">
      {days.map(({ day, events: dayEvents }, index) => {
        const isToday = isSameDay(day, today)
        return (
          <XStack
            key={dayKey(day)}
            gap="3"
            padding="2"
            {...(index > 0 && { borderTopWidth: 1, borderColor: 'border' })}
          >
            <View width="24" paddingTop="2" paddingLeft="1">
              <Text size="sm" weight="semibold" color={isToday ? 'primaryText' : 'foreground'}>
                {formats.agendaDay.format(day)}
              </Text>
            </View>
            <VStack flex={1} minWidth={0} gap="0-5">
              {dayEvents.map((event) => (
                <EventButton
                  key={event.id}
                  variant="row"
                  event={event}
                  label={eventLabel(event)}
                  onPress={onEventPress}
                >
                  <View
                    width="2"
                    height="2"
                    borderRadius="full"
                    backgroundColor={tones[event.tone ?? 'primary'].dot}
                  />
                  <VStack flex={1} minWidth={0} paddingVertical="1">
                    <Text size="sm" weight="medium" truncate>
                      {event.title}
                    </Text>
                    <Text size="xs" tone="muted">
                      {event.allDay
                        ? labels.allDay
                        : `${formats.time.format(event.start)} – ${formats.time.format(eventEnd(event))}`}
                    </Text>
                  </VStack>
                </EventButton>
              ))}
            </VStack>
          </XStack>
        )
      })}
    </VStack>
  )
}

import { type ReactNode, useMemo } from 'react'
import { type ColorTokens, type GetProps, View, isWeb, styled } from 'tamagui/unstyled'
import { VisuallyHidden } from '../visually-hidden/VisuallyHidden'
import { useRipple } from '../../hooks/useRipple'
import type { CalendarEvent, CalendarEventTone } from './events'

export type EventCalendarView = 'month' | 'week' | 'day' | 'agenda'

export interface EventCalendarLabels {
  today: string
  /** Read after today's date on iOS and Android, which have no `aria-current`. */
  todayMarker: string
  previousMonth: string
  nextMonth: string
  previousWeek: string
  nextWeek: string
  previousDay: string
  nextDay: string
  /** Names the view switcher. */
  view: string
  month: string
  week: string
  day: string
  agenda: string
  allDay: string
  /** Joins two times or days in event names: “9:00 AM to 10:00 AM”. */
  to: string
  /** A day's event count, in its name. */
  events: (count: number) => string
  /** Events a month day has no room for: “2 more”. */
  more: (count: number) => string
  /** The agenda of a month with no events. */
  noEvents: string
}

export const defaultLabels: EventCalendarLabels = {
  today: 'Today',
  todayMarker: 'today',
  previousMonth: 'Previous month',
  nextMonth: 'Next month',
  previousWeek: 'Previous week',
  nextWeek: 'Next week',
  previousDay: 'Previous day',
  nextDay: 'Next day',
  view: 'View',
  month: 'Month',
  week: 'Week',
  day: 'Day',
  agenda: 'Agenda',
  allDay: 'All day',
  to: 'to',
  events: (count) => (count === 0 ? 'no events' : count === 1 ? '1 event' : `${count} events`),
  more: (count) => `${count} more`,
  noEvents: 'No events this month',
}

/** Soft fills with their text color, and a solid dot for small screens. */
export const tones: Record<
  CalendarEventTone,
  { background: ColorTokens; color: ColorTokens; dot: ColorTokens }
> = {
  primary: { background: 'primarySoft', color: 'primarySoftForeground', dot: 'primary' },
  success: { background: 'successSoft', color: 'successSoftForeground', dot: 'success' },
  warning: { background: 'warningSoft', color: 'warningSoftForeground', dot: 'warning' },
  error: { background: 'errorSoft', color: 'errorSoftForeground', dot: 'error' },
  info: { background: 'infoSoft', color: 'infoSoftForeground', dot: 'info' },
  neutral: { background: 'muted', color: 'foreground', dot: 'mutedForeground' },
}

export function useFormats(locale: string | undefined) {
  return useMemo(() => {
    const format = (options: Intl.DateTimeFormatOptions) => new Intl.DateTimeFormat(locale, options)
    return {
      month: format({ month: 'long', year: 'numeric' }),
      day: format({ weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }),
      agendaDay: format({ weekday: 'short', month: 'short', day: 'numeric' }),
      monthDay: format({ month: 'short', day: 'numeric' }),
      monthDayYear: format({ month: 'short', day: 'numeric', year: 'numeric' }),
      weekdayShort: format({ weekday: 'short' }),
      weekdayLong: format({ weekday: 'long' }),
      time: format({ hour: 'numeric', minute: '2-digit' }),
      hour: format({ hour: 'numeric' }),
    }
  }, [locale])
}

export type Formats = ReturnType<typeof useFormats>

/** What every view needs from the root. */
export interface ViewContext {
  events: readonly CalendarEvent[]
  today: Date
  weekStartsOn: number
  formats: Formats
  labels: EventCalendarLabels
  /** Pressing a day opens it: the day view, `onDatePress`, or both. */
  openDay: ((day: Date) => void) | null
  onEventPress: ((event: CalendarEvent) => void) | null
  eventLabel: (event: CalendarEvent) => string
}

/** A web-only role: iOS and Android have no table or group roles. */
export const webRole = <T extends string>(role: T) => (isWeb ? role : undefined) as never

/**
 * Props that make a View a real button on web and an accessible one on
 * native. Set the padding yourself: a button has its own, and `padding`
 * here would replace a variant's.
 */
export const buttonProps = (label: string) =>
  ({
    render: 'button',
    role: 'button',
    'aria-label': label,
    cursor: 'pointer',
    ...(isWeb
      ? {
          type: 'button',
          borderWidth: 0,
          backgroundColor: 'transparent',
          // A button centers its text; events read from the start.
          style: { textAlign: 'left' as const },
        }
      : { accessible: true }),
  }) as const

const EventFrame = styled(View, {
  displayName: 'EventCalendarEvent',
  borderRadius: 'sm',
  outlineColor: 'focus-visible:ring',
  outlineStyle: 'focus-visible:solid',
  outlineWidth: 'focus-visible:2px',
  outlineOffset: 'focus-visible:1px',
  variants: {
    variant: {
      // One line in a month day or the all-day row.
      chip: {
        flexDirection: 'row',
        alignItems: 'center',
        minHeight: '5',
        paddingHorizontal: '1',
        paddingVertical: 0,
      },
      // Placed on the hours of the week and day views.
      block: {
        flex: 1,
        paddingHorizontal: '1',
        paddingVertical: '0-5',
        overflow: 'hidden',
      },
      // A line of the agenda.
      row: {
        flexDirection: 'row',
        alignItems: 'center',
        gap: '2',
        minHeight: '9 touchable:11',
        paddingHorizontal: '2',
        paddingVertical: 0,
        borderRadius: 'md',
      },
    },
  } as const,
})

export interface EventButtonProps extends Omit<GetProps<typeof EventFrame>, 'onPress'> {
  event: CalendarEvent
  label: string
  onPress: ((event: CalendarEvent) => void) | null
  children: ReactNode
}

/**
 * An event: a button when `onEventPress` is set, else its name in hidden
 * text, with what it shows hidden from screen readers.
 */
export function EventButton({
  event,
  label,
  onPress,
  variant = 'chip',
  children,
  ...props
}: EventButtonProps) {
  const tone = tones[event.tone ?? 'primary']
  const ripple = useRipple({
    color: tone.color,
    radius: { borderRadius: variant === 'row' ? 'md' : 'sm', ...props },
    disabled: !onPress,
  })
  const filled = variant !== 'row'
  const background = filled
    ? tone.background
    : onPress
      ? `transparent hover:accent${ripple.active ? '' : ' press:accentHover'}`
      : 'transparent'
  if (!onPress) {
    return (
      <EventFrame variant={variant} backgroundColor={background as ColorTokens} {...props}>
        <VisuallyHidden>{label}</VisuallyHidden>
        <View
          aria-hidden
          flexDirection={variant === 'block' ? 'column' : 'row'}
          {...rowLayout(variant)}
        >
          {children}
        </View>
      </EventFrame>
    )
  }
  return (
    <EventFrame
      variant={variant}
      {...buttonProps(label)}
      // After buttonProps, which clears a button's own background on web.
      backgroundColor={background as ColorTokens}
      {...(filled && { opacity: ripple.active ? 'press:1' : 'hover:0.85 press:0.75' })}
      onPress={() => onPress(event)}
      {...props}
      {...ripple.props}
    >
      {ripple.element}
      {children}
    </EventFrame>
  )
}

/** The hidden-label version wraps the content: it keeps the frame's layout. */
const rowLayout = (variant: EventButtonProps['variant']) =>
  variant === 'block'
    ? { flex: 1 }
    : {
        flex: 1,
        alignItems: 'center' as const,
        gap: variant === 'row' ? ('2' as const) : undefined,
      }

import { addDays, minutesInto, minutesPerDay, startOfDay } from './dates'

export type CalendarEventTone = 'primary' | 'success' | 'warning' | 'error' | 'info' | 'neutral'

export interface CalendarEvent {
  id: string
  title: string
  start: Date
  /**
   * When it ends. Default: an hour after `start`. For an all-day event, the
   * last day it covers (default: the day of `start`).
   */
  end?: Date
  /** Fills whole days, shown above the hours in the week and day views. */
  allDay?: boolean
  /** Color. Default `primary`. */
  tone?: CalendarEventTone
}

const hour = 60 * 60_000

export function eventEnd(event: CalendarEvent) {
  return event.end ?? (event.allDay ? event.start : new Date(event.start.getTime() + hour))
}

/** Whether the event covers any part of `day`. */
export function isOnDay(event: CalendarEvent, day: Date) {
  const dayStart = startOfDay(day)
  if (event.allDay) {
    return startOfDay(event.start) <= dayStart && dayStart <= startOfDay(eventEnd(event))
  }
  const dayEnd = addDays(dayStart, 1)
  const end = eventEnd(event)
  // An event with no length still shows on its day.
  if (end.getTime() <= event.start.getTime()) return event.start >= dayStart && event.start < dayEnd
  return event.start < dayEnd && end > dayStart
}

/** All-day events first, then by start, longer first, then by title. */
export function compareEvents(a: CalendarEvent, b: CalendarEvent) {
  if (!!a.allDay !== !!b.allDay) return a.allDay ? -1 : 1
  return (
    a.start.getTime() - b.start.getTime() ||
    eventEnd(b).getTime() - eventEnd(a).getTime() ||
    a.title.localeCompare(b.title)
  )
}

export function eventsOnDay(events: readonly CalendarEvent[], day: Date) {
  return events.filter((event) => isOnDay(event, day)).sort(compareEvents)
}

export interface PlacedEvent {
  event: CalendarEvent
  /** Minutes from the start of the day. */
  top: number
  bottom: number
  /** Overlapping events sit side by side: this one's column of `columns`. */
  column: number
  columns: number
}

/**
 * Places a day's timed events on its hours. Events that overlap share the
 * width in columns; each group of overlapping events gets as many columns
 * as it needs at its busiest.
 */
export function placeEvents(events: readonly CalendarEvent[], day: Date, minLength = 0) {
  const timed = eventsOnDay(events, day).filter((event) => !event.allDay)
  const placed: PlacedEvent[] = []
  let group: PlacedEvent[] = []
  let columnEnds: number[] = []
  let groupEnd = -1
  const closeGroup = () => {
    for (const item of group) item.columns = columnEnds.length
    group = []
    columnEnds = []
  }
  for (const event of timed) {
    // At least `minLength` tall, so a short event still has room for its title.
    const start = minutesInto(day, event.start)
    const bottom = Math.min(
      minutesPerDay,
      Math.max(minutesInto(day, eventEnd(event)), start + minLength),
    )
    const top = Math.min(start, Math.max(0, bottom - minLength))
    if (top >= groupEnd) closeGroup()
    let column = columnEnds.findIndex((end) => end <= top)
    if (column === -1) column = columnEnds.push(bottom) - 1
    else columnEnds[column] = bottom
    const item = { event, top, bottom, column, columns: 1 }
    group.push(item)
    placed.push(item)
    groupEnd = Math.max(groupEnd, bottom)
  }
  closeGroup()
  return placed
}

// Local calendar days: the time part is dropped, so days never shift with
// time zones. Core's Calendar keeps its own copies; these add weeks and minutes.

export function startOfDay(date: Date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

export function addDays(date: Date, days: number) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days)
}

/** Same day of the month, clamped to the target month's length (31 Jan + 1 → 28/29 Feb). */
export function addMonths(date: Date, months: number) {
  const first = new Date(date.getFullYear(), date.getMonth() + months, 1)
  const last = new Date(first.getFullYear(), first.getMonth() + 1, 0).getDate()
  return new Date(first.getFullYear(), first.getMonth(), Math.min(date.getDate(), last))
}

export function isSameDay(a: Date, b: Date) {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  )
}

export function isSameMonth(a: Date, b: Date) {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth()
}

export function startOfWeek(date: Date, weekStartsOn: number) {
  return addDays(startOfDay(date), -((date.getDay() - weekStartsOn + 7) % 7))
}

/** The days of the week holding `date`, from `weekStartsOn`. */
export function weekDays(date: Date, weekStartsOn: number, length = 7) {
  const start = startOfWeek(date, weekStartsOn)
  return Array.from({ length }, (_, i) => addDays(start, i))
}

/** The weeks that hold a day of `month`: four to six rows of seven days. */
export function monthWeeks(month: Date, weekStartsOn: number) {
  const first = new Date(month.getFullYear(), month.getMonth(), 1)
  const weeks: Date[][] = []
  for (let start = startOfWeek(first, weekStartsOn); ; start = addDays(start, 7)) {
    if (weeks.length && !isSameMonth(start, month)) break
    weeks.push(Array.from({ length: 7 }, (_, i) => addDays(start, i)))
  }
  return weeks
}

/** The days of `month`, in order. */
export function monthDays(month: Date) {
  const count = new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate()
  return Array.from(
    { length: count },
    (_, i) => new Date(month.getFullYear(), month.getMonth(), i + 1),
  )
}

export const minutesPerDay = 24 * 60

/**
 * Minutes from the start of `day` to `date` on the clock, clamped to that
 * day. By the clock, so a day with a daylight saving change still has 24 hours.
 */
export function minutesInto(day: Date, date: Date) {
  if (date < startOfDay(day)) return 0
  if (date >= addDays(day, 1)) return minutesPerDay
  return date.getHours() * 60 + date.getMinutes()
}

/** ISO date without time zones, for keys: `2026-10-28`. */
export function dayKey(date: Date) {
  const pad = (n: number) => String(n).padStart(2, '0')
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`
}

